function threeSumClosest(a, target) {
    const arr = [...a].sort((x, y) => x - y);
    let best = arr[0] + arr[1] + arr[2];
    for (let i = 0; i < arr.length - 2; i++) {
        let lo = i + 1, hi = arr.length - 1;
        while (lo < hi) {
            const sum = arr[i] + arr[lo] + arr[hi];
            if (Math.abs(sum - target) < Math.abs(best - target) ||
                (Math.abs(sum - target) === Math.abs(best - target) && sum < best)) best = sum;
            if (sum === target) return sum;
            else if (sum < target) lo++; else hi--;
        }
    }
    return best;
}

