function numSubarrayProductLessThanK(a, target) {
    if (target <= 1) return 0;
    let product = 1, count = 0, left = 0;
    for (let right = 0; right < a.length; right++) {
        product *= a[right];
        while (product >= target) { product /= a[left]; left++; }
        count += right - left + 1;
    }
    return count;
}

