function findUnsortedSubarray(a) {
    const sorted = [...a].sort((x, y) => x - y);
    let start = -1, end = -1;
    for (let i = 0; i < a.length; i++) {
        if (a[i] !== sorted[i]) { start = i; break; }
    }
    if (start === -1) return 0;
    for (let i = a.length - 1; i >= 0; i--) {
        if (a[i] !== sorted[i]) { end = i; break; }
    }
    return end - start + 1;
}

