function circularArrayLoop(a) {
    const n = a.length;
    const next = (i) => (((i + a[i]) % n) + n) % n;
    for (let i = 0; i < n; i++) {
        if (a[i] === 0) continue;
        const isForward = a[i] > 0;
        let slow = i, fast = i;
        let valid = true;
        while (valid) {
            slow = next(slow);
            if (a[slow] === 0 || (a[slow] > 0) !== isForward) { valid = false; break; }
            fast = next(fast);
            if (a[fast] === 0 || (a[fast] > 0) !== isForward) { valid = false; break; }
            fast = next(fast);
            if (a[fast] === 0 || (a[fast] > 0) !== isForward) { valid = false; break; }
            if (slow === fast) {
                if (slow === next(slow)) { valid = false; break; }
                return true;
            }
        }
    }
    return false;
}

