function countRangeSum(a, lower, upper) {
    const n = a.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    function sort(lo, hi) {
        if (hi - lo <= 1) return 0;
        const mid = (lo + hi) >> 1;
        let count = sort(lo, mid) + sort(mid, hi);
        let j = mid, k = mid;
        for (let i = lo; i < mid; i++) {
            while (j < hi && prefix[j] - prefix[i] < lower) j++;
